func readConfig(path string) ([]byte, error) {
  f, err := os.Open(path)
  if err != nil {
    return nil, err
  }
  defer f.Close() // fd is freed when the function returns

  buf := make([]byte, 4096)
  n, err := f.Read(buf)
  if err != nil {
    return nil, err
  }
  return buf[:n], nil
}

